INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lf49iMURaXW', 4, '{"title":"第902000820条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>274、草蒿,青蒿</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000820,"note":"\n【本经原文】一名青蒿。一名方溃。味苦，寒，无毒。治疥瘙痂痒，恶疮，杀虱，留热在骨节间，明目。生川泽。一名青蒿，一名方溃。  \n\n【产地】处处有之，可煮饮，亦可作食，自生于河岸或海滨，茎叶气味俱芬，入药，子功用亦同。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】青蒿为清虚热要药，主治虚痨骨蒸，烦热盗汗，疟痢虚热，血中伏热，明目。  \n\n【大明】补中益气，补劳。长毛发令黑不老，兼去蒜髪，杀风毒，心痛热黄，生捣汁服并贴之。  \n\n【容川】青蒿色青味苦，正治肝胆之相火，其节中必生红虫，乃感风化而生之虫，故青蒿为去风清热之要药，人之痨虫皆因肝气相火，相煽而生，假血以成质，故必骨蒸而生痨虫，青 蒿节以虫杀虫，消瘀去蒸，借虫以攻血，借风气以散郁火也。  \n\n【用量】普通一钱至二钱。 \n\n【禁忌】产后气虚，内寒作泻，及饮食停滞，泄泻者均忌，凡产后脾胃薄弱，忌与归地同用。 ","videoMemo":"","fangList":[],"bieMing":"青蒿"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '274、草蒿,青蒿', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yXm8g13A532', 4, '{"title":"第902000819条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>273、莨菪子  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000819,"note":"\n【本经原文】味苦，寒，有毒。治齿痛、出虫，肉痹拘急。使人健行、见鬼。多食令人狂走。久服轻身、走及奔马。强志，益力，通神。生海滨、川谷。一名横唐。","videoMemo":"","fangList":[],"bieMing":"莨菪子"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '273、莨菪子', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GilvbgWP8vc', 4, '{"title":"第902000818条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>272、桔梗  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000818,"note":"\n【本经原文】味辛，微温有小毒。治胸胁痛如刀刺，腹满，肠鸣幽幽，惊恐悸气。生山谷。\n\n【产地】生嵩高山谷。自生于山中向阳之地，处处皆有，叶似沙参，根亦相似而较白。 \n\n【性味】味苦辛。性微温：有小毒。 \n\n【主治】桔梗为宣肺祛痰要药，功能治痰壅气逆，胸胁气痛，利咽喉，治肺痈。 \n\n【别录】利五脏肠胃，补血气，除寒热风痹，温中消谷，疗喉咽痛，下蛊毒。 \n\n【甄权】治下痢，破血积气，消聚痰涎，去肺热气促嗽逆，除腹中冷痛，主中恶及小儿惊痫。\n\n【大明】下一切气，止霍乱转筋，心腹胀痛，补五劳，养气除邪辟温，破症瘕肺痈，养血排脓，补内漏及喉痹。 \n\n【元素】利窍，除肺部风热。清利头目咽嗌，胸膈滞气及痛，除鼻塞。 \n\n【药征】主治浊唾肿脓也，旁治咽喉痛。 \n\n【用量】普通八分至二钱。 \n\n【禁忌】凡攻补下焦药中勿入。气逆上升，不得下降，及邪在下焦，均忌。  ","videoMemo":"","fangList":[],"bieMing":"桔梗"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '272、桔梗', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QjVzPgDjwqF', 4, '{"title":"第902000817条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>271、葶苈  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000817,"note":"\n【本经原文】味辛，寒，无毒。治症瘕，积聚，结气，饮食寒热，破坚，逐邪，通利水道。生平泽及田野。一名大室，一名大适。 \n\n【产地】生藁城平泽。产我国河南陕西河北一带，有甜苦二种，今俱以甜者入药，且多以荠子或折蓂子混充，苦者绝少。 \n\n【性味】味辛苦，性大寒，无毒。 \n\n【主治】葶苈子为下气行水要药，功能降肺气，逐痰饮，止喘促，下膀胱水，治面目浮肿。\n\n【别录】下膀胱水伏留热气，皮间邪水上出面目浮肿，身暴中风，热沸痒，利小便，久服令人虚。 \n\n【甄权】疗肺壅土气咳嗽，止喘促，除肺中痰饮。 \n\n【容川】葶苈子多油，当能滑利，又有辛味，舆巴豆之辛有油相似，其味苦，与大黄之苦而滑润相似，故葶苈子隐含巴豆舆大黄二者之性，故能大泻肺中之痰饮脓血，性极速降，是猛 药类，故仲景配以大枣补之，入药前须要炒过，不炒则不香，不能散。 \n\n【药征】主治水病也，旁治肺痈结胸也。 \n\n【灵胎】泻肺气，利水道。 \n\n【用量】普通八分至二、三钱。 \n\n【禁忌】肿满由脾虚不能制水，小便不通，由膀胱虚无气以化者均忌，肺气虚者亦忌，宜大枣为辅、恶僵蚕。","videoMemo":"","fangList":[],"bieMing":"葶苈子"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '271、葶苈', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aw3HCOPXdIw', 4, '{"title":"第902000816条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>270、大黄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000816,"note":"\n【本经原文】味苦，寒，无毒。主下瘀血，血闭，寒热。破症瘕积聚，留饮，宿食，荡涤肠胃，推陈致新，通利水谷，调中化食，安和五脏。生山谷。 \n\n【产地】生河西山谷。产陕西甘肃四川等处，为多年生宿根草，根黄色，带有赤色之纹，故亦曰绵纹。 \n\n【性味】味大苦，性大寒，无毒（或作有毒）。 \n\n【主治】大黄为泻实热，荡积滞要药，主血闭热结，功能下瘀破症，荡涤肠胃，推陈致新，调中化食，大便燥结，女子经闭。 \n\n【别录】平胃，下气，除痰实，肠间结热，心腹胀满，女子寒血闭、小腹痛，诸老血留结。\n\n【甄权】通女子经候，利水肿，利大小肠，贴热肿毒，小儿寒热，时疾烦热蚀脓。 \n\n【大明】通宣一切气，调血脉，利关结，泄壅滞水气，温瘴热疟。 \n\n【元素】泻诸热不通，除下焦湿热，消宿食，泻心下痞痛。 \n\n【容川】大黄味苦大寒，形大而气烈，得地火之阴味，色黄，为火之退气所发见，故能退火，专下血分之结，以味厚有烈气，味既降又得气之助，故走脾胃，下行更速更远。寒性皆下引。其纯于苦味，又有雄烈之气，以气行其苦味，则走而不守。与黄连之守而不走，正好相反。大黄是治火之药，禀地气，入后天之血分也。 \n\n【药征】主通利及结毒也，故能治胸满腹满，腹痛及便秘，小便不利，旁治发黄瘀血脓肿。 \n \n【灵胎】攻凝结，消积滞。  \n\n【用量】普通五分至三钱。  \n\n【禁忌】凡气分病，及胃寒血虚，妊娠产后，均忌。  \n\n【炮制】拣去杂质，大小分开，浸泡约一小时，捞出沥干余水，切3 毫米厚，长宽约3 厘米块片，晾干或烘干即得。 熟大黄，取大黄片，用白酒调匀，待吸收酒后，蒸约4 小时，以蒸黑为度，停火闷一夜，冷却后取出，烘干即得，酒炒至黑后，则质轻味淡，能上清头目。","videoMemo":"","fangList":[],"bieMing":"大黄"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '270、大黄', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MISbRbSgDub', 4, '{"title":"第902000815条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>269、鸢尾  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000815,"note":"\n【本经原文】味苦，平，有毒。治蛊毒，邪气，鬼疰，诸毒。破症瘕，积聚，去水，下三虫。生山谷。  ","videoMemo":"","fangList":[],"bieMing":"鸢尾"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '269、鸢尾', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TrcLoZu9S3I', 4, '{"title":"第902000814条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>268、虎掌  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000814,"note":"\n【本经原文】味苦，温，有大毒。治心痛，寒热，结气，积聚，伏梁，伤筋，瘘，拘缓，利水道。生山谷。又名虎掌，今名天南星。 \n\n【产地】产我国北地，为多年生草本，生于山野阴处，根入药。 \n\n【性味】味苦，性温，有大毒。 \n\n【主治】天南星为祛风湿豁顽痰要药。主风痰壅塞，中风口噤，治口歪眼斜，痈毒疥癣，小 儿惊风。 \n\n【别录】治阴下湿，风眩。 \n\n【甄权】主疝瘕肠痛，伤寒时疾，强阴。 \n\n【大明】蛇虫咬，疥癣恶疮。 \n\n【元素】去上焦痰，眩晕。 \n\n【好古】补肝风虚，治痰功同半夏。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】误服麻唇舌，得防风则不麻，凡使，宜以矾汤或皂角水浸，至不麻乃止，忌铁，用竹刀切，阴虚燥痰忌用。  ","videoMemo":"","fangList":[],"bieMing":"南星,天南星,虎掌"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '268、虎掌', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MeS1SPSuIfN', 4, '{"title":"第902000813条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>267、半夏 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000813,"note":"\n【本经原文】味辛，平，有毒。治伤寒，寒热，心下坚，下气，喉咽肿痛，头眩，胸胀，咳逆、肠鸣，止汗。生山谷。一名地文，一名水玉。  \n\n【产地】生槐里川谷。产我国四川江浙及北地多有之，为多年生野草，根白色，入药。 \n\n【性味】味辛，性平，有毒。 \n\n【主治】半夏为除湿化痰，止呕止哕，开郁发表要药，主和胃，健脾，消积，化涎，顺气止咳，平逆止吐，治心痛，痞结，水饮，痰气，救五绝。   \n\n【别录】消心腹胸膈痰热结满，咳嗽上气，心下急痛坚痞，时气呕逆，消痈肿，疗痿黄，悦泽面目，堕胎。 \n\n【甄权】制者消痰下肺气，关胃健脾，止呕吐，去胸中痰。生者摩痈肿，除瘤瘿气。  \n\n 【大明】治吐食反胃，霍乱转筋，肠腹冷，痰疟。 \n\n【元素】治寒痰及形寒饮冷伤肺而咳，消胸中痞，膈上痰，除胸寒，和胃气，燥脾湿，治痰 厥头痛，消肿散结。  \n\n【好古】补肝风虚。 \n\n【容川】此生当夏之半，其根成于秋时，得燥金辛烈之气，故主降逆水饮，为阳明之药，此为真性。  \n\n【倪注】一般使用生半夏以止呕吐时，多加生姜以制其毒，重症病患之呕吐，唯此生半夏可治，学者当用之勿惧，今之医多不敢使用生药，因惧其毒性，实则此药又名婆婆药，意即可以让人失音，并不会致命，如果失音时，只须口含生姜片，须臾声自回。  \n\n【药征】主治痰饮呕吐也，旁治心痛逆满，咽中痛，咳悸，腹中雷鸣。 \n\n【灵胎】开肺降逆，消痰燥湿。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】一切血症及阴虚血少，津液不足之病，均忌，孕妇禁用，用姜佐则无害，反乌头，忌饴糖海藻羊血。  ","videoMemo":"","fangList":[],"bieMing":"半夏"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '267、半夏', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nSvOLVNIf88', 4, '{"title":"第902000812条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>266、天雄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000812,"note":"\n【本经原文】味辛，温，有大毒。治大风，寒湿痹，历节痛，拘挛缓急，破积聚、邪气，金 疮，强筋骨，轻身，健行。生山谷。  \n\n【产地】如乌头。 \n\n【性味】味甘辛，性温热，有毒。 \n\n【主治】天雄与附子之功用略同，惟一般对下元虚寒性机能衰退者及风痰症都多用天雄。 \n\n【别录】疗头面风，去来疼痛，心腹结聚，关节重，不能步行，除骨间痛，长阴气，强心，令人勇武力作不倦。 \n\n【用量】一般一钱至三钱 \n\n【禁忌】热症之人忌用  ","videoMemo":"","fangList":[],"bieMing":"天雄"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '266、天雄', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JZnVHNbD6te', 4, '{"title":"第902000811条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>265、乌头  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000811,"note":"\n【本经原文】，味辛，温，有大毒。治中风，恶风洒洒，出汗，除寒湿痹，咳逆上气，破积聚，寒热。其汁煎之，名射罔。杀禽兽。生山谷。一名奚毒，一名即子，一名乌喙。  \n\n【产地】产我国四川，故亦名川乌，与附子同种，称为附子之母。 \n\n【性味】味辛，性热，有大毒。 \n\n【主治】乌头为扶元回阳，补火退寒要药。功同附子。 \n\n【元素】主诸风，风痹血痹，半身不遂，除寒冷，温养脏腑，去心下坚痞，感寒腹痛。\n\n【好古】补命门不足，肝风虚。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】详见附子。","videoMemo":"","fangList":[],"bieMing":"乌头"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '265、乌头', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qmfRe8tzQ0O', 4, '{"title":"第902000810条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>264、附子  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000810,"note":"\n【本经原文】味辛，温，有大毒。治风寒，咳逆，邪气，温中，金疮，破症坚，积聚，血瘕，寒湿痿躄，拘挛，膝痛，不能行步。生山谷。一名茛。  \n\n【产地】产我国四川山野，亦可种植，冬播而春生苗，其初种之根，生成小块状者曰乌头，附乌头旁生而大者即附子，又附生而变形者曰天雄，小者毒强而大者毒少，故近人多取用附 子，亦曰大附子。  \n\n【性味】味辛甘，性大热，有大毒。  \n\n【主治】附子为扶元回阳，补火退寒要药，主寒湿痿躄，症瘕积聚，命门火衰，脾胃虚寒，治寒霍乱转筋，阳气暴脱，及真寒假热，阳气欲散，疗寒痰，寒痛，阴疽。  \n\n【别录】腰脊风寒，脚气寒冷弱，心腹冷痛，霍乱转筋，下痢赤白，温中，强阴，坚肌骨，又堕胎为百药长。  \n\n【元素】温暖脾胃，除脾湿，肾寒补下焦之阳虚。  \n\n【好古】督脉为病，脊强而厥。  \n\n【容川】人身之气，生于肾中一阳，实则借鼻孔吸入之天阳，歴心系，引心火下交于肾，附 子可以振肾阳以蒸动其气。其色纯黑，味辛烈，能从下焦扶阳补气，凡极阳极阴，皆有毒，附子之烈，正因其纯是坎阳之性，可以大毒，与肉桂不同，肉桂是补火，属地二之火气也，附子是助热，热生于水中，是得天水之阳，故附子入气分以助阳，能补命门之火，是以火化水，为肾与膀胱要药，火炙则无毒，水中之阳毒，过火则散，此阴阳相引之意。今用盐腌以去毒，使附子之性不全，非正法也，举凡温药皆秉木气，唯附子是水中之阳，为温肾达阳之正药，而得木火者，为得地二之火，能秉水中之阳，是得天一之阳。  \n\n仲景用炮附子，是制其毒也，用生附是以毒追风，毒因毒用，一生一炮，有一定之理。  \n\n【倪注】炮附子可以固表虚，去肺家寒症，生附子可以去里寒，二者截然不同。医者须明辨之，方可以用之无误。临床时可见病人因表虚而至真阳外越，我辈当以炮附子为救逆之剂。如脉细无力，病人昏迷不识人，此为里寒至极，因而真阳不足，当此之时又须以生附为主。  \n\n【药征】主逐水，能治恶寒，身体四肢及骨节疼痛，或沉重，或不仁，或厥冷，而旁治腹痛 失精下利。  \n\n【灵胎】逐寒邪，回阳气。  \n\n【用量】普通一钱至三钱，大剂一至二两。  \n\n【禁忌】乌头附子，用豆腐蒸熟或黑大豆蒸熟者，谓之熟乌头熟附子，味淡而力薄，不能用以救急，生者仅去皮脐，味咸而力猛，可以救急，宜慎用之，经疏曰，一切阳证火证热证，阴虚内热，血液衰少证，均忌，忌豉汁，畏饴。 ","videoMemo":"","fangList":[],"bieMing":"附子"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '264、附子', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pheG21V3Gz4', 4, '{"title":"第902000809条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>263、青琅玕,石珠  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000809,"note":"\n【本经原文】一名石珠。味辛，平，无毒。治身痒，火疮，痈伤，白秃，疥瘙，死肌。生平泽。  ","videoMemo":"","fangList":[],"bieMing":"青琅玕,石珠"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '263、青琅玕,石珠', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hLonJg5YIep', 4, '{"title":"第902000808条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>262、冬灰  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000808,"note":"\n【本经原文】一名藜灰。味辛，微温。治黑子，去疣息肉，疽蚀，疥瘙。生川泽。","videoMemo":"","fangList":[],"bieMing":"冬灰"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '262、冬灰', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pF5wisK6jDn', 4, '{"title":"第902000807条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>261、白垩  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000807,"note":"\n【本经原文】味苦，温，无毒。治女子寒热，症瘕，月闭，积聚，阴肿痛，漏下，无子。生山谷。  \n\n【产地】产河南山西，今他省亦多有之，画家用之，亦名画粉。 \n\n【性味】味苦，性温，无毒。 \n\n【主治】白垩主燥湿温臓，治吐血反胃泻痢，外用治风赤烂眼，疿疹搔痒。 \n\n【别录】阴肿痛瘘下无子，泻痢。 \n\n【甄权】疗女子血结。涩肠，止痢。 \n\n【大明】治鼻红血，痔瘘泄精，男子水藏冷，女子子宫冷。 \n\n【用量】普通数分至一钱。 \n\n【禁忌】用时宜取白色者，以盐汤飞过，以免结涩入肠，不可久服，否则损五脏，令人羸瘦。  ","videoMemo":"","fangList":[],"bieMing":"白垩"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '261、白垩', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F2dYH7ea5Da', 4, '{"title":"第902000806条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>260、卤咸 ,戎盐 ,大盐</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000806,"note":"\n【本经原文】味苦，寒，无毒。治大热，消渴，狂烦，除邪及吐下蛊毒，柔肌肤。一名寒石。生盐池。\n\n大盐，一名胡盐。寒，无毒。治肠胃结热，令人吐。生池泽。\n\n戎盐。主明目，目痛，益气，坚肌骨，去毒蛊。生北地。","videoMemo":"","fangList":[],"bieMing":"戎盐,卤咸,大盐"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '260、卤咸 ,戎盐 ,大盐', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MAfTpvpsT00', 4, '{"title":"第902000805条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>259、代赭  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000805,"note":"\n【本经原文】味苦，寒，无毒。治鬼疰，贼风，蛊毒，杀精物恶鬼，腹中毒，邪气，女子赤沃漏下。生山谷。一名须丸。 \n\n【产地】生齐国山谷。产各处山中，我国北方多有之，色赤。 \n\n【性味】味苦甘，性寒，【或作平】，无毒。 \n\n【主治】代赭石为镇虚祛，养阴血要药，功能避邪毒，治气逆，痰逆，反胃，血中热，血痹，血痢，女子赤白带下。 \n\n【别录】带下百病，产难胞不出，堕胎，养血气，除五脏血脉中热，血痹，血痢，大人小儿惊气入腹，及阴痿不起。 \n\n【大明】安胎健脾，止反胃，吐血，鼻衄，月经不止，肠风痔瘘泻痢，脱精，遗溺，小儿惊 痫疳疾，金疮长肉，辟鬼魅。 \n\n【用量】入煎剂钱半至三钱，水飞用五分至一钱。 \n\n【禁忌】下部虚寒及阳虚阴痿者忌，胎前慎用，畏天雄附子，凡使，醋淬，研末，水飞用。\n\n【容川】赭石重镇，其色赤，又入血分，故一名血师，因其能降血也。血为气之宅，故旋覆花代赭石汤，止噫气者，正是行血而降其气也。  ","videoMemo":"","fangList":[],"bieMing":"代赭石"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '259、代赭', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0sf17oOIoSa', 4, '{"title":"第902000804条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>258、粉钖  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000804,"note":"\n【本绖原文】味辛，寒，无毒。治伏尸，毒螫，杀三虫。锡镜鼻，平。治女子血闭，症瘕，伏肠，绝孕。生山谷。一名解锡。   \n\n【产地】以醋蒸铅化合而成，日本产此甚多，我国亦有制出，色白，故亦曰白粉，以其为铅所化，故亦曰铅粉。  \n\n【性味】味辛，性寒，无毒。 \n \n【主治】粉锡为外用要药，作膏药，治溃疡，制妆品，除皮病。 \n\n【别录】去鳖瘕。疗恶疮，止小便利，堕胎。 \n\n【甄权】治积聚不消，炒焦止小儿疳痢。 \n\n【大明】治痈肿瘘烂，呕逆，疗症瘕，小儿疳气。 \n\n【用量】普通皆外用，内服甚少，即用，亦宜轻量。 \n\n【禁忌】粉钖用以制妆品，久用蚀血，反使面色不华，故妇女常用粉者，去粉则面黄，且少血色。 ","videoMemo":"","fangList":[],"bieMing":"粉钖"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '258、粉钖', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DMOrD7IsW3O', 4, '{"title":"第902000803条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>257、铅丹,青铅  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000803,"note":"\n【本经原文】味辛，微寒，治吐逆，胃反，惊痫，癫疾，除热，下气，炼化还成九光，久服通神明。生平泽。  \n\n【产地】产我国四川山中，各国亦多有之，色青，故又名青铅。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】铅为镇心坠痰解毒要药，主治积聚，噎膈，恶疮，性重平肝逆，能堕胎。 \n\n【大明】主镇心安神，治伤寒毒气，反胃呕哕，蛇蜴所咬，炙熨之。 \n\n【用量】内服用量宜少，外用无定量。 \n\n【禁忌】性质重坠，能碍消化，虚者慎用，孕妇忌用。  ","videoMemo":"","fangList":[],"bieMing":"铅丹"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '257、铅丹,青铅', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b9k6MKCjVT8', 4, '{"title":"第902000802条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>256、礜石,青分石,制石,固羊石 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000802,"note":"\n【本经原文】味辛，大热，有毒。治寒热，鼠瘘，蚀疮，死肌，风痹，腹中坚癖，邪气，除热。生山谷。一名青分石，一名立制石，一名固羊石。","videoMemo":"","fangList":[],"bieMing":"礜石"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '256、礜石,青分石,制石,固羊石', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q4GA3vSOZzA', 4, '{"title":"第902000860条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>314、蜀椒  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000860,"note":"\n【本经原文】味辛，温，有毒。治邪气，咳逆，温中，逐骨节皮肤死肌，寒湿瘁痛，下气，久服之头不白，轻身，增年。生川谷。 \n\n【产地】椒之一种，产四川故名，今各省多有种植。 \n\n【性味】味辛，性温，有毒。 \n\n【主治】蜀椒为散寒祛湿，补火温中要药，主邪气咳逆，寒热痹痛，宣肺燥脾，治骨节皮肤 死肌，止呕逆，伏蚘虫。 【别录】除六腑寒冷，伤寒温疟，大风汗不出，心腹留饮宿食，肠澼下痢，泄精，女子字乳余疾，散风邪瘕结，水肿黄疸鬼疰蛊毒，杀虫鱼毒，开腠理，通血脉，坚齿发，明目，调关节，耐寒暑，可作膏药。 \n\n【甄权】治头风下泪，腰脚不遂，虚损留结，破血下诸石水，治咳嗽腹内冷痛，除齿痛。 \n\n【大明】破症结，开胸，治天行时气，产后宿血，壮阳，疗阴汗，暖腰膝，缩小便，止呕逆。\n\n【孟铣】益血，利五脏，下乳汁，灭瘢，生毛发。 \n\n【容川】辛温以散寒湿，能杀虫化湿。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】久服令人失明伤血脉，多忘乏气，杏仁为使，得盐味佳，中其毒者，火麻仁浆解之，闭口者有毒勿用。  ","videoMemo":"","fangList":[],"bieMing":"蜀椒"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '314、蜀椒', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xyq1y8Uub8k', 4, '{"title":"第902000859条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>313、巴豆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000859,"note":"\n【本经原文】一名巴菽．味辛，温，有大毒。治伤寒，温疟，寒热，破症瘕，结聚坚积，留饮痰癖，大腹水胀，荡筱五脏六腑，开通闭塞，利水谷道，去恶肉，除鬼毒、蛊疰邪物，杀 虫、鱼。生川谷。  \n\n【产地】产四川，出古之巴郡，故名，木高大，结实作房，内含之仁即巴豆。  \n【性味】味辛，性温，有毒。  \n\n【主治】巴豆为峻泻要药，主荡涤脏腑，开通闭塞，破症坚积聚，留饮痰澼，治大腹水胀，胎伤腹中，利水谷道，排恶疮脓血。 \n\n【别录】疗女子月闭烂胎，金疮脓血，不利丈夫，杀班蝥蛇虺毒，可练饵之益血脉。  \n\n【药性】治十种水肿，瘘痹落胎。 \n\n【日华】通宣一切病，泄壅滞，除风补劳，健脾开胃，消痰破血，排脓消肿毒，杀腹脏虫，治恶疮息肉，及疥癞子疮。 \n\n【元素】导气消积，去脏腑停寒，治生冷硬物所伤。 \n\n【容川】巴豆油滑，而主下降，故能利大便。味大辛故性烈，大热则悍，以悍烈行其滑利，故迅捷而不留也。 \n\n【药征】主治心腹胸膈之毒，兼治心腹卒痛，胀满吐脓。  \n\n【禁忌】凡一切汤散丸剂，切勿轻投，即不得以急证，亦须炒熟压令油极净，入分许即止，不得多用，芫花为使，畏大黄黄莲藜芦冷水，反牵牛，中巴豆毒，用冷水黄莲汁大豆汁解之效。","videoMemo":"","fangList":[],"bieMing":"巴豆"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '313、巴豆', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xeNPpRgDVPZ', 4, '{"title":"第902000858条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>312、芫花  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000858,"note":"\n【本经原文】一名去水。味辛，温，有小毒。治咳逆上气，喉鸣，喘，咽肿，短气，蛊毒，鬼疟，疝瘕，痈肿，杀虫、鱼。生川谷。 \n\n【产地】生淮源川谷。产我国河南以及北地山谷中，庭园亦可种植，为约三四尺之落叶灌木，花入药。 \n\n【性味】味辛（或作苦），性温，有毒（或作大毒）。 \n\n【主治】芫花为行水祛痰要药，主水肿，水饮，痰癖，利血脉，治疮毒，参看甘遂大戟等条。\n\n【别录】消胸中痰水喜唾，水肿，五水在五脏皮肤，及腰痛，下寒毒，肉毒，根疗疥疮，可用毒鱼。 【甄权】治心腹胀满，去水气寒痰，涕唾如胶，通利血脉，治恶风痹湿，一切毒风，四肢挛急，不能行步。 \n\n【大明】疗咳嗽瘴疟。 \n\n【药征】主逐水也，旁治咳掣痛。 \n\n【用量】普通七分至二钱。 \n\n【禁忌】时珍曰，饮有五，皆由内啜水浆。外受湿气，郁蓄而为留饮，芫花大戟甘遂，逐水泄热，能直达水饮巢囊隐癖之处，但可徐徐用之，取效甚捷，不可过剂，泄人元气，反甘草，能堕胎，孕妇忌用，醋制良，参看甘遂大戟条。  ","videoMemo":"","fangList":[],"bieMing":"芫花"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '312、芫花', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MHdhSTh4dgt', 4, '{"title":"第902000857条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>311、夏枯草  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000857,"note":"\n【本经原文】味苦，辛，寒，无毒。治寒热瘰，鼠瘘，头疮，破症，散瘿结气，脚肿，湿痹，轻身。生川谷。一名夕句，一名乃东。  \n\n【性味】味苦辛，性微寒，无毒。 \n\n【主治】夏枯草为瘰疬要药，主养阴血，散结毒，治目珠疼夜甚，阴肿赤白带下，消暑清湿。  \n\n【灵胎】泻湿热，散结气。\n\n【用量】普通一钱至三钱。  \n\n【禁忌】不详。  \n\n【容川】此以时为治之药，夏枯草生于冬末，长于三春，正得水木之气，遇夏则枯，因木当火令，其气退谢，故可用以退肝胆经之火。  \n\n【倪注】民间方使用单味夏枯草五钱，生鸡蛋带壳一只，用水二碗煮成一碗，将汤喝尽，去壳吃蛋，如果于健康时吃一剂，则终身不再犯扁桃腺炎。 ","videoMemo":"","fangList":[],"bieMing":"夏枯草"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '311、夏枯草', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ENOojulQyn8', 4, '{"title":"第902000856条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>310、牛扁  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000856,"note":"\n【本经原文】味苦，微寒，无毒。治身皮疮热气，可作浴汤，杀牛虱、小虫、又治牛病。生川谷。  ","videoMemo":"","fangList":[],"bieMing":"牛扁"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '310、牛扁', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('leoyvRIfkJJ', 4, '{"title":"第902000855条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>309、盖草  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000855,"note":"\n【本经原文】味苦，平，无毒。治久咳上气，喘逆，久寒，惊悸，痂疥，白秃，疡气，杀皮肤小虫。生川谷。","videoMemo":"","fangList":[],"bieMing":"盖草"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '309、盖草', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RInca2U8Jjt', 4, '{"title":"第902000854条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>308、陆英  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000854,"note":"\n【本经原文】味苦，寒，无毒。治骨间诸痹，四肢拘挛、疼酸，膝寒痛，阴痿，短气不足，脚肿。生川谷。  ","videoMemo":"","fangList":[],"bieMing":"陆英"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '308、陆英', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s5APtjni3Rw', 4, '{"title":"第902000853条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>307、石长生  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000853,"note":"\n【本经原文】一名丹草。味咸，微寒，有毒。治寒热，恶疮，大热，辟鬼气不祥。生山谷。\n\n【产地】产我国陕西，各处亦多有之，生于高山峻崖之上，四时不凋，固号长生。 \n\n【性味】味咸，性微寒，有毒。 \n\n【主治】石长生主积聚痈肿，豁痰利尿，功能散结凝排脓，治胸膈满闷，咳嗽喘满。为解毒杀虫要药。 \n\n【别录】下三虫。 \n\n【甄权】治疥癣，逐诸风，治百邪魁。 \n\n【用量】普通一钱至钱半。 \n\n【禁忌】不详。 ","videoMemo":"","fangList":[],"bieMing":"石长生"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '307、石长生', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YBMc2GF6JzK', 4, '{"title":"第902000852条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>306、蚤休  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000852,"note":"\n【本经原文】味苦，微寒，有毒。治惊痫，摇头。弄舌，热气在腹中，癫疾，痈疮，阴蚀，下三虫，去蛇毒。生川谷。一名蚩休。 \n\n【产地】处处有之，生于深山阴湿之地。 \n\n【性味】味苦，微寒，有毒。 \n\n【主治】蚤休主散结导热，治寒热，疟疾，癫疾，痈疽，瘰疬，解蛇毒虫（磨醋敷）。 \n\n【别录】癫疾痈疮，除蚀，下三虫，去蛇毒。 \n\n【大明】治胎风手足搐，能吐泄瘰疬。 \n\n【用量】普通五分至二钱，外用无定量。 \n\n【禁忌】以治外证，殊有功效，但其性苦寒，不宜多服，元气虚者忌之。  ","videoMemo":"","fangList":[],"bieMing":"蚤休"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '306、蚤休', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ylk57z4kIJM', 4, '{"title":"第902000851条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>305、鹿藿  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000851,"note":"\n【本经原文】味苦，平，无毒。治蛊毒，女子腰腹痛，不乐，肠痈，瘰疬，疡气。生山谷","videoMemo":"","fangList":[],"bieMing":"鹿藿"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '305、鹿藿', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6ylzb4azmY7', 4, '{"title":"第902000850条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>304、乌韭  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000850,"note":"\n【本经原文】味甘，寒，无毒。治皮肤往来寒热，利小肠膀胱气。生山谷石上。  ","videoMemo":"","fangList":[],"bieMing":"乌韭"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '304、乌韭', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SDs2f4hn9cp', 4, '{"title":"第902000849条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>303、蔺茹  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000849,"note":"\n【本经原文】味辛，寒，有小毒。主蚀恶肉，败疮，死肌，杀疥虫，排脓、恶血，除大风，热气，善忘，不乐。生川谷。","videoMemo":"","fangList":[],"bieMing":"蔺茹"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '303、蔺茹', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WZGMiOyY6BY', 4, '{"title":"第902000848条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>302、连翘  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000848,"note":"\n【本经原文】一名异翘，一名兰华。一名折根，一名轵，一名三廉。味苦，平，无毒。治寒热，鼠瘘，瘰疬，痈肿。恶疮，瘿瘤，结热，蛊毒。生山谷。  \n\n 【产地】生太山山谷。产山谷中及泽地，处处有之，四川产者为胜。 \n\n【性味】味苦辛，性平，无毒。 \n\n【主治】连翘为散结清火要药，主治疮疡，能清火解毒，消肿排脓，散血结气聚，去上焦热，通利小便。 \n\n【别录】去白虫。 \n\n【甄权】通利五淋，小便不通，除心家客热。 \n\n【大明】通小肠，排脓治疮疖，止痛，通月经。 \n\n【丹溪】泻心火，除脾胃湿热，治中部血证以为使。 \n\n【东垣】散诸经血结气聚，消肿。 \n\n【容川】连翘亦象心包，而质轻扬，味征苦，故轻扬上达，能清心与上焦头目之热，其无辛散之气，故不主散。 \n\n【灵胎】散郁火，治疮疡。 \n\n【倪注】此药常与银花同用，皆属味清而质轻，皆能升清气。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】连翘清而无补之药也，痈疽已溃及日久，火热由于虚，与脾胃薄弱作泄者均忌，忌火。","videoMemo":"","fangList":[],"bieMing":"连翘"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '302、连翘', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fcVm3eleizN', 4, '{"title":"第902000847条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>301、女青  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000847,"note":"\n【本经原文】味辛，平，有毒．治蛊毒，逐邪恶气，杀鬼，温疟，辟不祥，生山谷。一名雀瓢。  ","videoMemo":"","fangList":[],"bieMing":"女青"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '301、女青', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9xSXb8V4dO6', 4, '{"title":"第902000846条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>300、羊桃  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000846,"note":"\n【本经原文】味苦，寒，有毒。治熛热，身暴赤色，风水，积聚，恶疡，除小儿热，生山林川谷及田野。一名鬼桃，一名羊肠。","videoMemo":"","fangList":[],"bieMing":"羊桃"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '300、羊桃', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d1qxF7v1RnI', 4, '{"title":"第902000845条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>299、鬼臼  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000845,"note":"\n【本经原文】味辛，温，有毒。主杀蛊毒，鬼疰，精物，辟恶气不详，逐邪，解百毒。生山谷。一名爵犀，一名马目毒公，一名九臼。  ","videoMemo":"","fangList":[],"bieMing":"鬼臼"}}', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '2025-01-16T09:36:32.000Z', '299、鬼臼', '2025-01-16T09:36:32.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JTWJgwwrXd7', 4, '{"title":"第902000903条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>357、彼子  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000903,"note":"\n【本经原文】味甘，温，有毒。治腹中邪气，去三虫，蛇螫，蛊毒，鬼疰，伏尸。生山谷。","videoMemo":"","fangList":[],"bieMing":"彼子"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '357、彼子', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ESvOZn2A7X1', 4, '{"title":"第902000902条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>356、水斳,芹菜 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000902,"note":"\n【本经原文】一名水英。味甘，平，无毒。治女子赤沃，止血，养精，保血脉，益气，令人肥健，嗜食。生南海，池泽。又名芹菜。  \n\n【产地】处处有之。 \n\n【性味】味甘性平，有特殊的香味。 \n\n【主治】解热止血，健胃药，治女子血崩赤带，小儿暴热，大人酒后热。 \n\n【本经】主女子赤沃，止血养精，保血脉，益气，令人肥健，嗜食。  \n\n 【藏器】饮汁去小儿暴热，大人酒后热，鼻塞身热，去头中风热，利口齿，利大小肠。\n\n【大明】治烦渴、崩中，带下，五种黄病。 \n\n【圣惠】捣汁日服六七合，治小便出血。  ","videoMemo":"","fangList":[],"bieMing":"芹菜"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '356、水斳,芹菜', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k8Ka3G0HI0I', 4, '{"title":"第902000901条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>355、苦瓠  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000901,"note":"\n【本经原文】味苦，寒，有毒。治大水，面目四肢浮肿，下水，令人吐。生川泽。\n\n【产地】产我国山西，他省亦多有之，瓤及子入药。 \n\n【性味】味苦，性寒，有毒。 \n\n【主治】苦瓠主治水肿，利小便，通淋，治疮。 \n\n【苏敬】利石淋，吐呀嗽。囊结疰蛊，痰饮。又煮汁渍阴，疗小便不通。  \n\n 【藏器】煎汁滴鼻中出黄水，去伤冷鼻塞黄疸。 \n\n【大明】吐蛔虫。 \n\n【用量】普通二至三钱，大剂无定量。 \n\n【禁忌】服苦瓠过分吐利不止者，以黍穰灰汁解之。 ","videoMemo":"","fangList":[],"bieMing":"苦瓠"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '355、苦瓠', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nEeV0MwB84T', 4, '{"title":"第902000900条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>354、腐婢  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000900,"note":"\n【本经原文】小豆花也。味辛，平，无毒。治痎疟，寒热，邪气，泄利，阴不起，病酒头痛。\n\n【药征】主治心中懊恼，旁治心中结痛及心中满而烦也。 \n\n【用量】不定量。 \n\n【禁忌】无。  ","videoMemo":"","fangList":[],"bieMing":"腐婢"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '354、腐婢', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rLuNSV4TFlg', 4, '{"title":"第902000899条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>353、杏核仁  ,杏仁</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000899,"note":"\n【本经原文】味甘，温，有毒。治咳逆上气，肠中雷鸣，喉痹，下气，产乳，金疮，寒心，奔豚。生川谷。今名杏仁。 \n\n【产地】生晋山川谷。杏树处处有之，有多种，以产山西河南山东一带者为胜，仁入药。 \n\n【性味】味甘苦，性温，有小毒。 \n\n【主治】杏仁为咳逆痰气要药，主咳嗽气急，能下气平喘，治风寒痰滞，能宣肺解肌，除风散寒，润燥消积，利胸膈气滞。通大肠气闭。  \n\n【别录】惊痫，心下烦热，风气往来，时行头痛，解肌，消心下急满痛，杀狗毒。 \n\n【甄权】治腹痹不通，发汗主温病角气，咳嗽上气，喘促，入天门冬煎润心肺，和酪作汤润 声气。 \n\n【元素】除肺热，治上焦风燥，利胸膈气逆，润大肠气秘。 \n\n【容川】杏仁有油，但得苦味，无辛烈之气，故降而不及。色白属金，降气行痰，气降则血降，故凡吐血必咳痰，痰为气分，因气逆而血升，故引出其血也。 \n\n【药征】主治胸间停水也，故治喘咳，而旁治短气结胸，心痛，形体浮肿。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】凡杏子性皆热，小儿多食致疮痈膈热，多食动宿疾，产妇尤忌，杏仁双仁者有毒能杀人，阴虚咳嗽，肺家有虚热痰者均忌，恶黄","videoMemo":"","fangList":[],"bieMing":"杏仁"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '353、杏核仁 ,杏仁', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dXFJGholI55', 4, '{"title":"第902000898条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>352、桃核仁  ,桃仁</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000898,"note":"\n桃花——杀疰恶鬼，令人好颜色。 桃枭——在树不落，微温，主杀百鬼精物。 桃毛——平，主下血瘕，寒热积聚，无子。 桃蠹——杀鬼，辟邪恶不祥。生川谷。 \n\n【本经原文】味苦。平。主治瘀血。血闭瘕邪气。杀小虫。\n\n【产地】处处有之，以产河南陕西者为良，仁入药。 \n\n【性味】味苦甘，性平，无毒。主治瘀血。血闭瘕邪气。杀小虫。 \n\n【主治】桃仁为破血润燥要药，主行瘀血，消心下坚硬，治血晕血痞血积血痢，血热燥痒，蓄血发狂，通月经。 \n\n【别录】止咳逆上气，消心下坚硬，除卒暴击血，通月血，止心腹痛。 \n\n【元素】治血结血秘血燥，通润大便。破蓄血。 \n\n【孟铣】杀三虫，又每夜嚼一枚和蜜涂乎面良。 \n\n【容川】桃花红而仁味苦，皆得地火之性，仁在核中，又象人心，味苦有生气，是正入心中，故桃仁能破血，亦能生血。气属阳，血属阴，瘀血阻气，则阳不入阴，蒸热汗出，宜破其血，使气得入于血中，则不壅热，桃仁主之。 \n\n【灵胎】逐瘀血，除邪气。 \n\n【倪注】痘家勿用，因仁有生气，可令痘长。 \n\n【药征】主治瘀血，少腹满痛，兼治肠痈及妇人经水不利。 \n\n【用量】普通一钱至二至三钱。 \n\n【禁忌】生桃实多食，令人膨胀及生疮疽，与鳖同食患心痛，服术人忌之，作脯食，益颜色，肺病宜之。桃仁散而不收，泻而无补，过用或不当，能使血下不止，损伤真阴，故凡经闭由 于血枯，产后腹痛由于血虚，大便闭涩由于津液不足者均忌，双仁者有毒，不可食。 ","videoMemo":"","fangList":[],"bieMing":"桃仁"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '352、桃核仁 ,桃仁', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UXSKQShSEgB', 4, '{"title":"第902000897条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>351、衣鱼  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000897,"note":"\n【本经原文】味咸，温，无毒。治妇人疝瘕，小便不利，小儿中风，项强，皆宜摩之。生平泽。一名白鱼。  \n\n【产地】产湖中，即白鲤鱼也。  \n\n【性味】甘平无毒。味薄不美，故渔人时而弃之。  \n\n【主治】去水气愈肿也。  \n\n【用量】属食物类，无定量。  \n\n【禁忌】无。  ","videoMemo":"","fangList":[],"bieMing":"衣鱼"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '351、衣鱼', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Uet5dy4snfh', 4, '{"title":"第902000896条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>350、萤火  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000896,"note":"\n【本经原文】一名夜光。味辛。微温，无毒。主明目，小儿火疮，伤热气，蛊毒，鬼疰，通神精。生阶地、池泽。  ","videoMemo":"","fangList":[],"bieMing":"萤火"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '350、萤火', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sknMxHdk5Yq', 4, '{"title":"第902000894条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>348、地胆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000894,"note":"\n【本经原文】味辛，寒，有毒。治鬼疰，寒热，鼠瘰，恶疮，死肌，破症瘕，堕胎。生川谷。一名蚖青。  ","videoMemo":"","fangList":[],"bieMing":"地胆"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '348、地胆', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3sLOsnIjN1k', 4, '{"title":"第902000895条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>349、鼠妇  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000895,"note":"\n【本经原文】味酸，温，无毒。治气癃不得小便，妇人月闭，血症，痫，痉，寒热，利水道。生平谷及人家地上。一名负燔，一名蝛。 \n\n【产地】处处有之，多在下湿处瓮器底及土坎中。 \n\n【性味】味酸，性温，无毒。 \n\n【主冶】鼠妇主利水道，去瘀积，治久疟寒热，妇人月闭，能堕胎。 \n\n【日华】主气癃不得小便，妇人月闭血瘕，痫痓，寒热，利水道，堕胎。 \n\n【用量】普通钱许。 \n\n【禁忌】孕妇忌之","videoMemo":"","fangList":[],"bieMing":"鼠妇"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '349、鼠妇', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4O4MF4qPUz9', 4, '{"title":"第902000893条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>347、马陆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000893,"note":"\n【本经原文】味辛，温，有毒。治腹中大坚症，破积聚，息肉，恶疮，白秃。生川谷。一名百足。  ","videoMemo":"","fangList":[],"bieMing":"马陆"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '347、马陆', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qOOr5O2DmC1', 4, '{"title":"第902000892条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>346、蝼蛄 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000892,"note":"\n【本经原文】味咸，寒，无毒。治产难，出肉中剌，溃痈肿，下哽噎，解毒，除恶疮，生平泽。一名蟪蛄，一名天蝼。 \n\n【产地】处处有之，穴地粪壤中而生，夜则外出求食，有短翅，能低飞。 \n\n【性味】味咸，性寒，无毒（或作有毒）。 \n\n【主治】蝼蛄主行水解毒，下哽噎，利二便，治大腹水肿，通石淋，疗难产，外涂出肉剌，治痈肿。  \n\n【日华】治水肿，头面肿。  \n\n【丹溪】治口疮甚效。  \n\n【用量】普通二至三钱。 \n\n【禁忌】欲利大小便，用自腰以后半截，但其性急，虚者忌之，入药取雄者（善鸣而非腹较小），去翅足炒用。  ","videoMemo":"","fangList":[],"bieMing":"蝼蛄"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '346、蝼蛄', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O7c3ps97dB7', 4, '{"title":"第902000891条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>345、蜣螂  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000891,"note":"\n【本经原文】味咸，寒，有毒。治小儿惊痫，瘛瘲，腹胀，寒热，大人癫疾，狂易。生池泽。  \n一名蛣蜣。  \n\n【产地】产山区树间。  \n\n【性味】味咸，性寒。 \n\n【主治】功能通二便，治食痫，癫疾狂阳，脱肛，灸疮出血。 \n\n【时珍】治大小便不通，下利赤白，脱肛，一切痔瘘疔肿，附骨疽疮，灸疮出血不止，鼻中息肉，小儿重舌。  ","videoMemo":"","fangList":[],"bieMing":"蜣螂"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '345、蜣螂', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yCLaTOCAruv', 4, '{"title":"第902000890条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>344、雀瓮,知了,蝉蜕</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000890,"note":"\n【本经原文】味甘，平，无毒．治小儿惊痫，寒热，结气，蛊毒，鬼疰。生树枝间。一名躁舍。又名知了。今名蝉蜕。  \n\n【产地】生夏日树间。 \n\n【性味】昧甘咸性寒。 \n\n【主冶】为解热镇惊退翳之药，治小儿热惊，皮肤风热瘾疹。目生翳瘴，治小儿哑病及阴肿。\n\n【别录】治小儿惊痫，妇人生子不下，烧灰酒服，治久病。 \n\n【藏器】研末一钱，用华水调服，治哑病。 \n\n【宗奭】除目昏除翳，以水煎汁服，治小儿疮疹出不快，甚良。 \n\n【时珍】治头风眩晕，皮肤风热，痘疹作痒，破伤风，及疔肿毒疮，大人失音，小儿噤风天吊，惊哭夜啼，阴肿。 \n\n【用量】一般五分至一钱。  \n\n【禁忌】无。  \n\n【附方】 小儿惊啼——蝉蜕后半截为末，入薄荷脑少许，每服一匙蜜调下，亦治夜啼。瘾疹——皮肤起红瘢痒，蝉蜕与薄荷叶等分为末，每酒服一钱，日三。 痘后目翳——蝉蜕为末，每服一钱，日二。 小儿阴肿——蝉蜕半两煎水洗，内服五苓散，即肿消痛止。 ","videoMemo":"","fangList":[],"bieMing":"蝉蜕,知了,雀瓮"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '344、雀瓮,知了,蝉蜕', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jx2FcmlijtH', 4, '{"title":"第902000889条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>343、石蚕  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000889,"note":"\n【本经原文】味咸，寒，有毒。治五癃，破石淋，堕胎。肉，解结气，利水道，除热。生池泽。一名沙虱。  ","videoMemo":"","fangList":[],"bieMing":"石蚕"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '343、石蚕', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F665klkNUrw', 4, '{"title":"第902000888条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>342、贝子,贝齿,大贝</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000888,"note":"\n【本经原文】味咸，平，有毒。治目翳，鬼疰，腹痛，下血，五癃，利水道。生东海池泽。一名贝齿。又名大贝。 \n\n【产地】产海滨，壳略似三角形，口作锯齿状，有白色紫色之花者。 \n\n【性味】味咸，性平，有毒。 \n\n【主治】贝齿主散结热，利水道，治目翳，狂热，鬼疰蛊毒，搜湿毒，通五癃。 \n\n【别录】温病寒热，解肌，散结热。 \n\n【甄权】伤寒狂热。 \n\n【弘景】烧研点目去翳． \n\n【李珣】下水气浮肿，小儿疳蚀，吐乳。 \n\n【用量】普通二至三钱。 \n\n【禁忌】蜜醋浸透，虾米酒淘入药，无湿热结滞者勿用。","videoMemo":"","fangList":[],"bieMing":"贝子,贝齿,大贝"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '342、贝子,贝齿,大贝', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3CxN4Izwf8i', 4, '{"title":"第902000887条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>341、斑蟊</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000887,"note":"\n【本经原文】味辛寒，有毒。治寒热，鬼疰，虫毒，鼠瘘，恶疮，疽蚀，死肌，破石癃。生川谷。一名龙尾。  \n\n【产地】处处有之，大豆叶上甲虫也，有黄斑文。 \n\n【性味】味辛，性寒，有毒。 \n\n【主治】斑蟊主瘰疬虫毒，治血积，蚀死肌，破石癃，堕妊娠死胎，敷鼠瘘恶疮。 \n\n【别录】血积，伤人肌，治疥癣，堕胎。 \n\n【甄权】治瘰疬，通利水道。 \n\n【日华】疗淋疾，傅恶疮，瘘烂。 \n\n【用量】普通二分至三分。 \n\n【禁忌】有毒，用时去翅足，同糯米炒熟，或麸炒过，醋煮用，亦有用米取气不取质者，生  \n用则吐泻，马刀为使，畏巴豆丹参空青，恶曾青甘草豆花，惟性猛毒，力能烂肉堕胎，体虚 者忌之  ","videoMemo":"","fangList":[],"bieMing":"斑蟊"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '341、斑蟊', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dpnSnp8LnQf', 4, '{"title":"第902000886条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>340、水蛭  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000886,"note":"\n【本经原文】味咸平，有毒。主逐恶血，瘀血，月闭，破血瘕，积聚，无子，利水道。生池泽。一名至掌。 \n\n【产地】生雷泽池泽。产池泽中，处处有之，好吸附人畜肌肤而吮其血。 \n\n【性味】味咸，性平，有毒。 \n\n【主治】水蛭主逐恶血，破征积，治折伤坠扑，蓄血疼痛，堕胎通经，外治肿毒。 \n\n【别录】堕胎。 \n\n【药性】治女子月闭，欲成干血劳。 \n\n【藏器】痈肿毒肿。 \n\n【宗奭】治折伤坠蹼蓄血有功。 \n\n【容川】锐而善入，又能允血，故主攻血积。 \n\n【灵胎】逐瘀破积。 \n\n【用量】普通一至二钱。 \n\n【禁忌】破血泄结之品，不可轻服，误吞水蛭，入腹难死，久则生子，食人肝血，腹痛难忍，面目黄瘦，用田中泥一两，雄黄二钱为丸，分四服，开水下，即随大便而出，桂圆肉包烟油吞之，即下，此物畏石灰食盐。  ","videoMemo":"","fangList":[],"bieMing":"水蛭"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '340、水蛭', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S2Gy9RSFWxh', 4, '{"title":"第902000885条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>339、蜈蚣  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000885,"note":"\n【本经原文】味辛，温，有毒。治鬼疰，虫毒，啖诸蛇、虫、鱼毒，杀鬼物老精，温疟，去三虫。生川谷。  \n\n【产地】处处有之，赤足者良。  \n\n【性味】味辛，性温，有毒。 \n\n【主治】蜈蚣为驱风散结要药，主小儿惊痫，风搐脐风，治寒热积聚，堕胎，去恶血，制蛇毒。  \n\n【别录】疗心腹寒热积聚，堕胎，去恶血。  \n\n【日华】治癥瘕。  \n\n【用量】普通一至二钱。 \n\n【禁忌】蜈蚣有毒，必风气暴烈，药病相当，乃可设，或过剂，以蚯蚓桑皮解之，畏蛞蝓，被蜈蚣螫伤，捣蛞蝓涂之即止痛。","videoMemo":"","fangList":[],"bieMing":"蜈蚣"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '339、蜈蚣', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BM7TE74QxSm', 4, '{"title":"第902000884条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>338、翳螉  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000884,"note":"\n【本经原文】味辛，平，无毒。治久聋，咳逆，毒气，出刺，出汗。生川谷或人屋间。  ","videoMemo":"","fangList":[],"bieMing":"翳螉"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '338、翳螉', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1N3x0upcvux', 4, '{"title":"第902000883条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>337、白颈蚯蚓  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000883,"note":"\n【本经原文】味咸，寒，无毒。治蛇瘕，去三虫，伏尸，鬼疰，虫毒，杀长虫。仍自化作水。生平土。今名地龙。 \n\n【产地】田中或韭田中及地下，处处有之。 \n\n【性味】味甘酸，性寒，无毒。 \n\n【主治】蚯蚓主解毒，傅疮，小便不通，赤白痢疾。 \n\n【藏器】主赤白久热痢，取一升炒烟尽，沃汁半升滤净饮之。 \n\n【日华】小儿阴囊忽虚热肿痛，以生甘草汁入轻粉末调涂之，以盐研傅疮去热毒，及蛇犬伤。\n\n【苏敬】傅狂犬伤，出犬毛神效。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】内服宜煎汁澄清，不必用渣。  ","videoMemo":"","fangList":[],"bieMing":"白颈蚯蚓"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '337、白颈蚯蚓', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p6StU4kVjfB', 4, '{"title":"第902000882条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>336、蛇蜕  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000882,"note":"\n【本经原文】味咸，平，无毒。治小儿百二十种惊痫，瘈瘲，癫疾，寒热，肠痔，虫毒，蛇痫。生川谷及田野。一名龙子衣，一名蛇符，一名龙子单衣，一名弓皮。 \n\n【产地】处处有之，多蜕于石上及人家墙屋间，白色如银者入药。 \n\n【性味】味咸甘，性平，无毒（或作小毒）。 \n\n【主治】蛇蜕主瘈瘲癫疾，弄舌摇头，治皮肤疥癣疮疡，明目退翳。 \n\n【别录】大人五邪，言语僻越，止呕逆，明目，烧之疗诸恶疮。 \n\n【甄权】喉痹，百鬼魅。 \n\n【日华】炙用辟恶，止小儿惊悸客热，煎汁傅疬疡，白瘢风，摧生。 \n\n【孟铣】安胎。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】性走窜，凡小儿惊痫癫疾，非外邪客忤而由肝心虚者忌用，孕妇忌之，畏磁石及酒，得火熬之良。","videoMemo":"","fangList":[],"bieMing":"蛇蜕"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '336、蛇蜕', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bwf6LZO3BVo', 4, '{"title":"第902000881条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>335、马刀  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000881,"note":"\n【本经原文】味辛，微寒，有毒。治漏下赤白，寒热，破石淋，杀禽兽，贼鼠。生江湖池泽及东海。  ","videoMemo":"","fangList":[],"bieMing":"马刀"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '335、马刀', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rSH1Nac6sIr', 4, '{"title":"第902000880条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>334、虾蟆  ,蟾蜍</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000880,"note":"\n【本经原文】味辛，寒，有毒。治邪气，破症坚血，痈肿，阴疮，服之不患热病。生江湖池泽。  ","videoMemo":"","fangList":[],"bieMing":"蟾蜍,虾蟆"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '334、虾蟆 ,蟾蜍', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hIlUXddgWYy', 4, '{"title":"第902000879条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>333、六畜毛蹄甲  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000879,"note":"\n【本经原文】味咸，平，有毒。治鬼疰，虫毒，寒热，惊痫，癫，痉，狂走。骆驼毛，尤良。 ","videoMemo":"","fangList":[],"bieMing":"六畜毛蹄甲"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '333、六畜毛蹄甲', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fnZhTYwCAR6', 4, '{"title":"第902000878条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>332、（鼯）鼠</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000878,"note":" \n【本经原文】微温。主堕胎，令产易。生平谷。  ","videoMemo":"","fangList":[],"bieMing":"鼯鼠"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '332、（鼯）鼠', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K3hKZc8maWa', 4, '{"title":"第902000877条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>331、麋脂  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000877,"note":"\n【本经原文】味辛，温，无毒。治痈肿，恶疮，死肌，风寒湿痹，四肢拘缓不收，风头肿，气通腠理。生山谷及淮海边。一名官脂。  ","videoMemo":"","fangList":[],"bieMing":"麋脂"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '331、麋脂', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L4C4T8FlsI0', 4, '{"title":"第902000876条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>330、豚卵  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000876,"note":"\n【本经原文】味甘，温，无毒。治惊痫，癫疾，鬼疰，虫毒，除寒热，奔豚，五癃，邪气，挛缩。悬蹄，平。主五痔，伏热在肠，肠痈内蚀。一名豚颠。  ","videoMemo":"","fangList":[],"bieMing":"豚卵"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '330、豚卵', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4lLoDrDFCp8', 4, '{"title":"第902000875条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>329、蔓椒  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000875,"note":"\n【本经原文】味苦，温，无毒。治风寒湿痹歴节疼，除四肢厥气，膝痛。生川谷及丘冢间。一名豕椒。  ","videoMemo":"","fangList":[],"bieMing":"蔓椒"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '329、蔓椒', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5xd95iW9cRS', 4, '{"title":"第902000874条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>328、栾花  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000874,"note":"\n【本经原文】味苦，寒，无毒。治目痛，泪出，伤眦，消目肿。生川谷。","videoMemo":"","fangList":[],"bieMing":"栾花"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '328、栾花', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AVK5w1fWPD2', 4, '{"title":"第902000873条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>327、药实根  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000873,"note":"\n【本经原文】一名连木。味辛，温，无毒。治邪气，诸痹疼酸，续绝伤，补骨髓。生山谷。  ","videoMemo":"","fangList":[],"bieMing":"药实根"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '327、药实根', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t7Pbw4jkW0p', 4, '{"title":"第902000872条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>326、鼠李  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000872,"note":"\n【本经原文】治寒热，瘰疬疮。生田野。今少用。 \n\n【产地】处处有之。 \n\n【性味】味苦性寒，有微毒，其皮味苦性寒，无毒。 \n\n【主治】解毒，破积杀虫药，治瘰疬，疝瘕腹胀，天花黑陷，疥癣有虫。皮可治热毒及疳虫。\n\n 【大明】治水肿腹胀满。 \n\n【苏敬】下血及碎肉，除疝瘕积冷，九蒸酒渍，服三合。 \n\n【别录】鼠李皮治身皮热毒。 \n\n【孟铣】治口疳蛀齿，及疳虫蚀人脊骨者，煮浓汁灌之良。  ","videoMemo":"","fangList":[],"bieMing":"鼠李"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '326、鼠李', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sKegUBC6HnX', 4, '{"title":"第902000871条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>325、溲疏  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000871,"note":"\n【本经原文】味辛，寒，无毒。治身皮肤中热，除邪气，止遗溺。生川谷及田野故丘墟地。  \n可作浴汤。  ","videoMemo":"","fangList":[],"bieMing":"溲疏"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '325、溲疏', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dJC7eCR1pbF', 4, '{"title":"第902000870条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>324、黄环  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000870,"note":"\n【本经原文】一名凌泉，一名大就。味苦，平，有毒。治蛊毒，鬼疰，鬼魅，邪气在臓中，除咳逆，寒热。生山谷。","videoMemo":"","fangList":[],"bieMing":"黄环"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '324、黄环', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X7VZZMx4LRY', 4, '{"title":"第902000869条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>323、古南  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000869,"note":"\n【本经原文】一名鬼目。味辛，平，有毒。主养肾气，内伤阴衰，利筋骨皮毛。实，杀虫毒，破积聚，逐风痹。生山谷。","videoMemo":"","fangList":[],"bieMing":"古南"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '323、古南', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1TaLANoe8B3', 4, '{"title":"第902000868条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>322、梓白皮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000868,"note":"\n【本经原文】味苦，寒，无毒。治热，去三虫。花、叶，捣敷猪疮。饲猪，肥大三倍。生山谷。  \n\n【产地】生河内山谷。生山区。 \n\n【性味】味苦，性寒。 \n\n【主治】梓白皮能解热，杀虫，亦治反胃疮疥，梓实为排水利尿药，治浮肿有效。 \n\n【别录】疗目中疾，主吐逆胃反，小儿热疮，身头烦热，蚀疮，煎汤浴之，并捣敷。\n\n【大明】煎汤洗小儿壮热，一切疮疥，皮肤搔痒。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】寒症忌用。  ","videoMemo":"","fangList":[],"bieMing":"梓白皮"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '322、梓白皮', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3omJ577Vjos', 4, '{"title":"第902000867条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>321、桐叶  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000867,"note":"\n【本经原文】味苦，寒，无毒。治恶蚀疮着阴。皮，治五痔，杀三虫，花，主敷猪疮，饲猪，肥大三倍。生山谷。  \n\n【产地】产山区。  \n\n【性味】桐叶及桐木皮俱味苦，性寒。  \n\n【别录】桐木皮疗奔豚气病。 \n\n【甄权】桐木皮治五淋，沐发去头风，生发滋润。  \n\n 【时珍】桐叶消肿毒，生发，桐木皮治恶出疮，小儿丹毒，煎汁涂之。  \n\n【用量】一般三钱至五钱。  \n\n【禁忌】无。  \n\n【附方】 手足浮肿——圣惠方，桐叶煎汁渍之，并饮少许，加小豆良。肘后方：削桐木煮汁洗，并饮少许。 发落不生——桐叶一把，麻子仁三升，米泔煮汤去渣，日日洗之。（肘后） 眼见诸物——禽虫飞走，乃肝胆之疾，青桐（紫花者）花，酸枣仁，元明粉，羌活各一两为末，每服二钱，水煎和渣服，日三。（经验方）  ","videoMemo":"","fangList":[],"bieMing":"桐叶"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '321、桐叶', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5zecqLLbK1b', 4, '{"title":"第902000866条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>320、雷丸  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000866,"note":"\n【本经原文】一名雷矢。味苦，寒，有小毒。主杀三虫，逐毒气，胃中热，利丈夫，不利女子。作膏摩，除小儿百病。生山谷土中。 \n\n【产地】产我国河南陕西湖北等地，生土中，为竹之余气所结，故亦曰竹苓。 \n\n【性味】味苦（或作咸），性寒，有小毒（或作无毒）。 \n\n【主治】雷丸为消积杀虫要药，主除皮中热结，逐毒气，杀诸虫，作摩膏治小儿百病。 \n\n【别录】作摩膏除小儿百病，逐邪气恶风汗出，除皮中热结，积虫毒，白虫寸白，自出不止，久服令人阴痿。 \n\n【甄权】逐风，主痫狂走。 \n\n【用量】普通一至二钱。 \n\n【禁忌】不利女子，多服令人阴痿。  ","videoMemo":"","fangList":[],"bieMing":"雷丸"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '320、雷丸', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KdEA3xGGTnv', 4, '{"title":"第902000865条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>319、莽草  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000865,"note":"\n【本经原文】味辛，温，有毒。治风头，痈肿，乳痈，疝瘕，除结气，疥瘙，杀虫、鱼。生山谷。  \n\n【产地】处处有之。  \n\n【性味】味辛性温有毒。  \n\n 【主治】消肿，杀虫要药，治痈肿，瘰疬，疥癣，白秃，头风痛及皮肤麻痹。 \n\n【别录】疗喉痹不通，乳难，头风痒，可用沐，勿内服。 \n\n【甄权】治风疽疝气肿坠，凝血，治瘰疬，除风湿，不入汤服，主头疮白秃，杀虫，与白蔹，赤小豆为末，鸡子白调之如糊，敷毒肿，干更易之。 \n\n【用量】无定量。  \n\n【禁忌】只可做沐汤及外敷药，不可内服。  ","videoMemo":"","fangList":[],"bieMing":"莽草"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '319、莽草', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dRrY2FvGFJV', 4, '{"title":"第902000864条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>318、郁李仁  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000864,"note":"\n【本经原文】味酸，平，无毒。治大腹水肿，面目四肢浮肿，利小便水道，根，治齿断肿，龋齿，坚齿。生高山川谷及丘陵。一名爵李。  \n\n【产地】产我国陕西甘肃等地，他处亦多有之，其树虽似李树，而结子小若樱桃，核仁入药。  \n\n【主治】郁李仁为润燥破血，泄气行水要药，主大肠气滞，关格不通，治大腹水肿，四肢浮肿，破结气，利水道。  \n\n【孟铣】破癖气，下四肢水，酒服四十九粒，能泻结气。  \n\n【甄权】阳中结气，关格不通 \n\n【大明】泄五脏膀胱急痛，宣腰胯冷脓，消宿食下气。  \n\n【元素】破血润燥。 \n\n【东垣】专治大肠气滞，燥湿不通。\n\n【宗奭】研和龙脑点赤眼。  \n\n【禁忌】性专下降，善导大肠燥结，利周身水气，然下后多令人津液亏损，燥结愈甚，乃治标救急之药，非可常用，津液不足者忌用之。  ","videoMemo":"","fangList":[],"bieMing":"郁李仁"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '318、郁李仁', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a5K6d75oGk6', 4, '{"title":"第902000863条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>317、楝实,金铃子,川楝子,苦楝子 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000863,"note":"\n【本经原文】味苦，寒，有小毒。治温疾，伤寒，大热，烦狂，杀三虫，疥，疡，利小便水道。生山谷。今名金铃子。又名川楝子。苦楝子。  \n\n【性味】金铃子味苦，性微寒，其皮味苦，性微寒，有小毒。 \n\n【主治】为解热，利尿，镇痛要药，治妇女白带，疝气及心腹诸痛症。苦楝皮杀虫治疥癣，亦可为蔬菜杀虫药。  \n\n【别录】苦楝皮治疣虫，利大小肠。  \n\n【东垣】入心及小肠，止上下腹痛。  \n\n【括要】泻膀胱，治诸疝虫痔，能入肝舒筋，导小肠，膀胱之热，为疝气要药。\n\n【用量】一般一钱至三钱。  \n\n【禁忌】胃虚寒者禁之。","videoMemo":"","fangList":[],"bieMing":"楝实,金铃子,川楝子,苦楝子"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '317、楝实,金铃子,川楝子,苦楝子', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1C664NZc6bS', 4, '{"title":"第902000862条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>316、柳花,柳絮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000862,"note":"\n【本经原文】味苦，寒，无毒。治风水，黄疸，面热黑。叶，治马疥，痂疮。实，主溃痈，逐脓血。生川泽。一名柳絮。  \n\n【产地】江南一带，生湖畔河堤处。  \n\n【性味】柳絮，柳枝，柳叶，柳根皆味苦，性寒。  \n\n【主治】柳絮为祛湿，解热，止痛药，治黄疸，湿痹,金疮及脚气。柳叶可疗疥，洗漆疮，解热毒，止痛。柳枝及根白皮能解热，止痛，消肿。  \n\n【别录】主痂疥，恶疮，金疮，实主溃脓，逐脓血，子汁疗渴。  \n\n【甄权】主止血，治湿痹，四肢挛急膝痛。 \n\n【日华】煎膏续筋骨长肉止痛，主服金石人大发热闷，汤火疮毒入腹闷热，及疔毒。  \n\n【苏敬】柳枝与根主治痰热淋疾，可为浴汤，洗风肿疮疡，煮酒漱齿痛。\n\n【时珍】煎服治黄疸，白浊，酒煮熨诸肿痛，去风，止痛，消肿。  \n\n【附方】 金疮出血——柳絮封之即止。 脚多汗湿——柳絮着鞋袜内穿之。 眉毛脱落——柳叶阴干为末，以姜汁在铁器内调膏，夜夜抹之。 黄疸初起——柳枝煮浓汁半升，顿服。 乳痈妒乳——初起坚紫，众疗不愈，柳根皮熟捣，火温棉裹慰之，冷更易，一宿消。  \n\n【用量】一般一钱至三钱。\n\n【禁忌】寒症忌用。  ","videoMemo":"","fangList":[],"bieMing":"柳花,柳絮"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '316、柳花,柳絮', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aKRHNaZQ0m2', 4, '{"title":"第902000861条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>315、皂荚  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000861,"note":"\n【本经原文】味辛，咸，温，有小毒。治风痹，死肌，邪气，风头，泪出，利九窍，杀精物。生川谷。 \n\n【产地】皂树处处有之，结实名皂荚，以肥而多脂为良，其刺亦可入药。 \n\n【性味】味辛咸，性温，有小毒。 \n\n【主治】皂荚为通窍搜风拔毒杀虫要药，主风痹死肌，消痰涎，破坚症，治肠痈腹痛，溃散疮疡。 \n\n【别录】疗腹胀满，消谷，除咳嗽，囊结，妇人胞不落，明目益精，可为沐药不入汤。 \n\n【甄权】破坚症腹中痛，能堕胎，又将浸酒中取尽其精，煎成膏涂帛，贴一切肿痛。  \n【大明】通关节，头风，消痰杀虫，治骨蒸，开胃，中风口噤。  \n\n【宗奭】溽暑久雨时，合苍术烧烟辟瘟疫邪湿气。  \n\n【汪机】烧烟熏久痢脱肛。\n\n【用量】普通一钱至三钱。  \n\n【禁忌】药性颇峻，中病即止，凡由阴虚火炎，煎熬成痰，热极生风，至卒然仆蹶，不可遽用稀涎，耗其津液，致经络无以营养，为拘挛偏废之病，孕妇亦忌，畏空青人参苦参，伏丹砂粉霜硫黄磠砂。  \n\n皂角刺——即皂树刺，味辛性温，无毒，主通关窍，消痈疽，搜风，杀虫，治风疠，腹内生疮，妇人妒乳，胎衣不下。功同皂荚而力更锋锐，能直达病所，通风涎咽喉阻塞、治痈疽未 溃均妙，痈疽已溃者、气虚者与孕妇均禁用。  ","videoMemo":"","fangList":[],"bieMing":"皂荚"}}', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '2025-01-17T08:43:55.000Z', '315、皂荚', '2025-01-17T08:43:55.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nrgyCHap6IW', 4, '{"title":"第902001028条・第五章  增补神农本草经不足部分","description":"<p>28、灶心土  ,伏龙肝</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001028,"note":" ——治吐血，下血，胃家损伤之重症者。今人称伏龙肝。  \n\n【产地】乡下土灶烧之多年者佳，新土无效。 \n\n【性味】味甘性温平，功能补土利湿，修补胃壁之损伤。 \n\n【主治】胃出血，呕吐血，大便黑等。 \n\n【仲景】黄土汤用之，治疗便血吐血等。 \n\n【用量】一般三钱至五钱。 \n\n【禁忌】无。  ","videoMemo":"","fangList":[],"bieMing":"伏龙肝"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '28、灶心土 ,伏龙肝', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uctQwl3ykmL', 4, '{"title":"第902001027条・第五章  增补神农本草经不足部分","description":"<p>27、小麦 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001027,"note":" ——养心除烦，利溲止血。  \n\n【产地】处处有之，北方者为良。 \n\n【性味】味甘，性平，微寒，无毒。 \n\n【主治】小麦主除客热，养心气，为服食滋养之品。 \n\n【别录】主除客热，止烦渴咽燥，利小便，养肝气，止漏血唾血，令女子易孕。  \n\n【思邈】养心气，心病宜食之。\n\n【宗奭】煎汤饮治暴淋。  \n\n【素问】麦属火，心之谷也。  \n\n【圣惠方】小麦饭治疗烦热少睡多渴。  \n\n【用量】普通二至三钱。 \n\n【禁忌】脾虚作胀者，不甚相宜，入药，宜完用，皮肉不可分拆，拆则性温，明面不能消热止烦也。  \n\n【附录】 浮小麦——麦之性轻，入水浮起者，味咸性寒无毒，主益气除烦。治盗汗自汗，骨蒸虚热，妇人劳热。 麦苗——味辛性寒，主消酒毒，暴热，酒疸目黄，并捣汁日饮。  ","videoMemo":"","fangList":[],"bieMing":"小麦"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '27、小麦', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bdk76jAQTQ8', 4, '{"title":"第902001026条・第五章  增补神农本草经不足部分","description":"<p>26、神曲  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001026,"note":"\n——辛能散气，甘调中，温开胃，化水谷，消积滞。  \n\n【产地】处处有之，乃以青篙苍耳野蓼自然汁杏仁泥赤小豆未和白面，如造酱法酿制者，药铺多于伏日为之。  \n\n【性味】味甘，性温，无毒。  \n\n【主治】神曲为消食化痰要药，主化水谷宿食，行气调中，健脾开胃，治症结胀满，泄泻痢疾。  \n\n【本草】痰逆症结，泻利胀满：回乳下胎，治目病。  \n\n【药性】主化水谷宿食症结积滞，健脾暖胃。  \n\n【元素】养胃气，治赤白痢。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】脾阴虚胃火盛者忌之，虚胀者亦不宜，又能落胎，孕妇宜少食。 ","videoMemo":"","fangList":[],"bieMing":"神曲"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '26、神曲', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bp3cAjdPBGb', 4, '{"title":"第902001025条・第五章  增补神农本草经不足部分","description":"<p>25、白前  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001025,"note":"\n——长于降气，下痰止嗽，治肺气壅实，胸膈逆满。  \n【产地】山野多年生草，根死似细辛而大。白色，坚直易折，嘉谟曰，似牛膝短小柔软，能弯者为白微，长坚易折者为白前。  \n\n【性味】辛苦味甘，性微温，无毒。 \n\n【主治】白前为下气降痰要药，主治咳逆上气，肺病痰喘。  \n\n【别录】主胸胁逆气，咳嗽上气，呼吸欲绝。  \n\n【大明】主一切气，肺气烦闷，贲豚肾气。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】肺虚哽气者忌。  \n\n【吴克潜】白前能祛痰而利肺气，寇氏称其能保定肺气，治嗽多用。以温药相左尤佳，而时 珍谓其性无补益，虽寇氏称其能保肺气，但其功能专于降气，气降故痰亦下，故惟肺气壅实，兼有痰凝塞者，用之无不奏效，若虚者则不宜，之二说者，可并存也，盖惟其泻肺不补，而痰乃能降，气乃能平，惟其祛痰降气，而肺乃得保，气乃得安，正可以互相发明也。 ","videoMemo":"","fangList":[],"bieMing":"白前"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '25、白前', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8uckTePqZYd', 4, '{"title":"第902001024条・第五章  增补神农本草经不足部分","description":"<p>24、薤白  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001024,"note":" ——调中助阳，散血生肌，泄下焦太肠气滞。  \n\n【产地】处处有之，叶似韭而阔，多白而无实，入药去青留白。 \n\n【性味】味辛苦，性温，无毒。 \n\n【主治】薤白为滑利散结要药，主胸痹剌痛，泄痢后重，温中助阳，下气散血，除寒热，治带下。 \n\n【本经】主金疮，疮败。 \n\n【别录】归骨，除寒热，去水气，温中散结气，作羹食利病人，诸疮中风寒水气肿痛，捣涂之。  \n\n 【日华】煮食耐寒，调中补不足，止久痢冷泻。 \n\n【东垣】治泄痢下重，能泄下焦阳明气滞。 \n\n【思邈】心病宜食之，利产妇。 \n\n【孟铣】治女人带下赤白，作羹食之，骨哽在咽不去者，食之即下。 \n\n【苏敬】白者补益，赤者疗金疮及风，生肌肉。 \n\n【宗奭】与蜜同捣，涂汤火伤甚速。 \n\n【药征】主治心胸痛而喘息咳唾也，旁治背痛，心中痞。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】发热病不宜多食，不可与牛肉同食，令人作症瘕。  ","videoMemo":"","fangList":[],"bieMing":"薤白"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '24、薤白', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q4581wU56Ac', 4, '{"title":"第902001023条・第五章  增补神农本草经不足部分","description":"<p>23、新绛  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001023,"note":" ——主止血行血。  \n\n【产地】即大红帽之纬也。 \n\n【性味】烧炙后用，味苦辛。 \n\n【主治】主要用于止血行血。 \n\n【用量】一般五分至一钱。 \n\n【禁忌】忌与活血化血之药同用。  ","videoMemo":"","fangList":[],"bieMing":"新绛"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '23、新绛', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xX0F0OUibv0', 4, '{"title":"第902001022条・第五章  增补神农本草经不足部分","description":"<p>22、木通  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001022,"note":"\n【产地】木通古名通草，多自生山野，庭园亦可栽植，各省有之，茎入药。 \n\n【性味】味辛苦（或作辛甘）性平，无毒。 \n\n【主治】木通为导湿热，利小便要药，主降心火，清肺热，化津液，止大渴，治淋沥，水肿。  \n【别录】疗脾疽常欲眠，心烦哕，出音声，治耳聋，散痈肿诸结不消，及金疮恶疮，鼠瘘踒折，齆鼻息肉，堕胎。 \n\n【甄权】治五淋，利小便，开关格，治人多唾，主水肿浮大。 \n\n【孟铣】利诸经脉寒热不通之气。 \n\n【士良】理风热小便数急痛，小腹虚满，宜煎汤并葱饮有效。 \n\n【大明】安心除烦，止渴退热，明耳目，治鼻塞。通小肠下水，破积聚血块，排脓，治疮疖，止痛推生下胞，女人血闭，月候不匀，天行时疾，头痛目眩；羸劣，乳结，下乳。 \n\n【藏器】利大小便，令人心宽下气。 \n\n【李珣】主诸痿疮，喉痹咽痛，浓煎含咽。 \n\n【冬垣】通经利窍，导小肠火。 \n\n【用量】普通七分至二钱。 \n\n【禁忌】凡精滑不梦自遗，及阳虚气弱，内无湿热者忌，孕妇禁用","videoMemo":"","fangList":[],"bieMing":"木通"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '22、木通', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rLAXxhjz9m0', 4, '{"title":"第902001021条・第五章  增补神农本草经不足部分","description":"<p>21、郁金  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001021,"note":"\n【产地】产四川广东及台湾琉球等地，为多年生之宿根草，根茎似芋，内暗褐色或黄色，其香能及远。 \n\n【性味】味辛苦，性寒，无毒。 \n\n【主治】郁金为凉血破瘀要药，功能开血中之郁，泄血中之热，治吐血。溺血，恶血留积，失心癫狂。 \n\n【唐本】主血积下气，生肌止血，破恶血，血淋，尿血，金疮。 \n\n【甄权】单用治女人宿血气心痛，冷气结聚，温醋摩傅之，亦治马胀。 \n\n【丹溪】治吐衄，妇人倒经，痘毒入心。 \n\n【元素】凉心。 \n\n【东垣】治阳毒入胃，下血频痛。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡病属真阴虚极，阴分火炎，迫血妄行，溢出上窍，而非气分拂逆，肝气不平，以致伤肝吐血者，均忌。  ","videoMemo":"","fangList":[],"bieMing":"郁金"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '21、郁金', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q576VC3vQmV', 4, '{"title":"第902001020条・第五章  增补神农本草经不足部分","description":"<p>20、猪胆</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001020,"note":"\n【产地】处处有之。  \n\n【性味】猪胆汁味苦性寒，无毒。 \n\n【主治】主清心明目，凉肝胆，治目赤目翳，小儿疳瘦，著名方剂有猪胆汁方。（用猪胆汁和醋少许，灌入谷道中，少顷大便出宿垢），治阳明热结于下，大便不通者。  \n\n【禁忌】寒实者禁忌。","videoMemo":"","fangList":[],"bieMing":"猪胆"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '20、猪胆', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t8Zzoxq0tEX', 4, '{"title":"第902001019条・第五章  增补神农本草经不足部分","description":"<p>19、鸡子黄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001019,"note":" ——本经无记载。  \n\n【产地】处处有之。  \n\n【性味】味甘性平。  \n\n【主治】镇心安脏，益气补血。清咽开音，散热定惊。止嗽止痢，利产安胎。用醋煮食，治赤白久利。胎衣不下，吞卵黄二三枚，解发刺喉，令吐即下。取蛋壳，细研，调以麻油，擦痘毒神效。  \n\n【用量】一般一日二三枚。\n\n【禁忌】多食另人滞闷。  ","videoMemo":"","fangList":[],"bieMing":"鸡子黄 "}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '19、鸡子黄', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y1F3c1oCMay', 4, '{"title":"第902001018条・第五章  增补神农本草经不足部分","description":"<p>18、三七  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001018,"note":" ——本经无记载。  \n\n【产地】产我国湖广一带，山野自生，庭园亦可栽植，茎高二三尺，根作团块。 \n\n【性味】味甘，微苦，性温，无毒。 \n\n【主治】三七为散瘀定痛要药，功能散一切恶血，保一切新血，治血瘀成肿成痛，外敷能消肿止血。为云南白药之主药。 \n\n【日华】金鱼将死，入山漆叶（三七叶）汁于鱼口，即活，无名疮疖，捻叶敷之。  \n\n【倪注】举凡内外伤，诸烂疮，乳痈等都可以用，镇痛止血。\n\n【用量】普通钱半至三钱，大剂一两左右。 \n\n【禁忌】无。  ","videoMemo":"","fangList":[],"bieMing":"三七"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '18、三七', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HP2pn4x1Mww', 4, '{"title":"第902001017条・第五章  增补神农本草经不足部分","description":"<p>17、甘李根白皮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001017,"note":" ——本经无记载。  \n\n【性味】味咸性大寒。 \n\n【主治】为解热药，治消渴，奔豚气逆。 \n\n【别录】李根白皮治消渴，止心烦，逆奔豚气。 \n\n【孟铣】将之炙黄煎汤，日再饮之，治女人卒赤白带下。\n\n【甄权】治脚下气，主热毒烦躁，煮汁服止消渴 \n\n【用量】一般三钱至五钱。 \n\n【禁忌】津液不足者忌。  ","videoMemo":"","fangList":[],"bieMing":"甘李根白皮"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '17、甘李根白皮', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sg9Z2y6pJcD', 4, '{"title":"第902001016条・第五章  增补神农本草经不足部分","description":"<p>16、粳米  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001016,"note":" ——粳：硬也，糯：懦也、补脾清肺。  \n\n【产地】我国东南诸省。粳乃稻米之总称，有早中晚三收，晚者得金气多，性凉，尤能清热。俗话：北粳凉，南粳温，白粳凉，红粳温，新米食之，动气。陈米佳，冲淡可以养胃。煮汁  \n\n煎汤，取其调胃，利小便，去湿热，除烦渴之功。 \n\n【性味】甘凉，得天地中和之气，色白入肺。 \n\n【主治】和胃补中，除烦清热，煮汁止渴。 \n\n【仲景】以清热补不足。 \n\n【张文潜】粥能畅胃气，生津液，每晨空腹食之，所补不细。与脏腑相宜者唯此最佳。 \n\n【用量】可以日常服用。 \n\n【禁忌】无禁忌。  ","videoMemo":"","fangList":[],"bieMing":"粳米"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '16、粳米', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5UIac1ZNUtQ', 4, '{"title":"第902001015条・第五章  增补神农本草经不足部分","description":"<p>15、白芷  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001015,"note":" ——行手足阳明，入手太阴而为阳明主药、故治头面诸疾。  \n\n【产地】处处有之，根有轮节或隆起，外面色淡黄褐，气味甚香。\n\n【性味】味辛，（或作甘）性温，无毒。色白入肺。  \n\n【主治】白芷为散风发表要药，功能通窍去湿，疗风行血，止头痛，和肠胃，烧之辟邪气。\n\n【别录】疗风邪，久渴，吐呕，两胁满，头眩目痒。 \n\n【甄权】能蚀脓，止心腹血刺痛，女人沥血腰痛血崩。 \n\n【大明】治目赤努肉，去面皯疵瘢，补胎瘘滑落，破宿血，补新血，乳痈，发背，一切痈疮 疥癣，止痛排脓。  \n\n【元素】解利手阳明头痛，中风寒热，及肺经风热，头面皮肤风痹燥痒。  \n\n【用量】普通五分至钱半。 \n\n【禁忌】呕吐由于火，瘘下赤白，阴虚火炽，病由血热所至者，均忌，恶旋覆花，制雄黄硫黄。  \n\n【吴克潜】白芷为肺胃大肠三经气分药，亦入三经血分，擅散风去湿之功，配白芷治偏正头风，齿痛，带下者，成方颇多。 ","videoMemo":"","fangList":[],"bieMing":"白芷"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '15、白芷', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PVvmYZzocpH', 4, '{"title":"第902001014条・第五章  增补神农本草经不足部分","description":"<p>14、乳香  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001014,"note":"\n【产池】产西南热地及西藏等处，为树中流出之脂液，凝结成块者，入药。 \n\n【性味】味苦辛，性微温，无毒。 \n\n【主治】乳香为活血伸筋要药，主通行周身经络，去风散瘀，活血定痛，托疮毒，消痈疽。\n\n【别录】主风水毒肿，去恶气，伏尸，痈疹痒毒。 \n\n【之才】治不眠。 \n\n【大明】下气，益精，补腰膝，治肾气，止霍乱冲恶，中邪气心腹痛疰气，煎膏止痛长肉。\n\n 【元素】补肾，定诸经之痛。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】痈疽已溃，不宜服，诸疮脓多时，未宜遽用。","videoMemo":"","fangList":[],"bieMing":"乳香"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '14、乳香', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UycOrNVj9Ky', 4, '{"title":"第902001013条・第五章  增补神农本草经不足部分","description":"<p>13、没药  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001013,"note":"\n【产地】产我国南部热地，为树中流出之脂液，凝结成塽者，入药。 \n\n【性味】味苦辛，性平，无毒。 \n\n【主治】没药为散血消肿定痛生肌要药，主破血止痛，治折伤瘀血，消肿毒。 \n\n【开宝】主破血止痛，疗金疮杖疮，诸恶疮，痔瘘，卒下血，目中翳晕痛肤赤。  \n\n 【李珣】堕胎，产后心腹血气痛，并入丸散服。 \n\n【大明】破症瘕宿血，损伤瘀血，消肿痛。 \n\n【好古】心胆虚，肝血不足。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】凡骨节痛，胸腹胁肋痛，非由血瘀而由血虚者，产后恶露去多，腹中虚痛者，痈疽已溃者，目赤肤翳非血热甚者均忌。 \n\n【吴克潜】打扑跌损，皆伤筋络，气血不行，瘀痈作痛，乳香没药，皆能止痛消肿生肌，故二药多相兼而用。  ","videoMemo":"","fangList":[],"bieMing":"没药"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '13、没药', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JTQdkWE55Er', 4, '{"title":"第902001012条・第五章  增补神农本草经不足部分","description":"<p>12、蒴翟细叶  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001012,"note":"\n——现无资料可查（出于王不留行散中）。","videoMemo":"","fangList":[],"bieMing":"蒴翟细叶"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '12、蒴翟细叶', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AiLXPrBLRU8', 4, '{"title":"第902001011条・第五章  增补神农本草经不足部分","description":"<p>11、鸡矢白  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001011,"note":"\n——（鸡矢白散）  \n【产地】处处有之。为鸡食砂岩后排出之大便中，色白者。\n\n【性味】味苦，性微寒，无毒。  \n\n【主治】主行水消积，治鼓胀，疗转筋入腹，破石淋，利二便，下气破血，治伤寒寒热中风贼风风痹白虎风，贴风痛头痛，止遗溺，灭瘢痕，小儿客忤惊啼，解金银毒，酒服疗乳妒乳 痈乳头破裂，外敷秃疮耳疮瘰疬。  \n\n【素问】治臌胀。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】酒服最佳。 ","videoMemo":"","fangList":[],"bieMing":"鸡矢白"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '11、鸡矢白', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o6B28lzY3Hw', 4, '{"title":"第902001010条・第五章  增补神农本草经不足部分","description":"<p>10、豆豉,香豉  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001010,"note":"\n【产地】处处有之，为一般食物调味之用。 \n\n【性味】色黑味咸，无毒，形如心，色如肾，味咸入肾，故治火中之木，令水火相济。\n\n【主治】主治心中懊憹也，旁治心中结痛及心中满而烦也。 \n\n【倪注】经方中之栀子豆豉汤主治心中懊憹，一般多用于病愈后之失眠烦躁。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】多无禁忌。  ","videoMemo":"","fangList":[],"bieMing":"豉"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '10、豆豉,香豉', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WKWTas36xAQ', 4, '{"title":"第902001009条・第五章  增补神农本草经不足部分","description":"<p>9、柏叶（侧柏叶）  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001009,"note":"\n【产地】处处有之，山野最宜种植，树高大可作木材，叶侧生者入药，名侧柏叶。  \n\n【甄权】治冷风历节疼痛，止尿血。 \n\n【大明】灸罯冻疮，烧取汁涂头，黑润鬓发。 \n\n【苏颂】傅汤火伤，止痛减瘢，服之疗蛊痢，作汤常服杀五脏虫，益人。  \n\n【禁忌】畏菊花诸石，忌面，得酒良，焙干用。 \n\n侧柏子壳——和鸡子清调服，解砒霜毒。 \n\n侧柏子枝节——治风痹，历节风，疗虫疥。 \n\n侧柏油——外用治诸癣痈毒，游丹秃疮，头面耳部黄水疮，杀虫虱。\n\n侧柏根皮——主凉血，生毛发，治火灼烂疮。 ","videoMemo":"","fangList":[],"bieMing":"柏叶,侧柏叶"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '9、柏叶（侧柏叶）', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WDwwwEG52Nw', 4, '{"title":"第902001008条・第五章  增补神农本草经不足部分","description":"<p>8、饴糖 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001008,"note":" ——补中益气。  \n\n【产地】处处有之，乃以米麦制成者。 \n\n【性味】味甘，性温，无毒。 \n\n【主治】饴糖为滋润肺脾，健胃补中要药，主补虚冷，益气力，治胃气枯燥，脾弱不运。 \n\n【别录】主补虚乏，止渴，去血。 \n\n【思邈】补虚冷，益气力，止肠鸣咽痛，治唾血，消痰，润肺止嗽。 \n\n【孟铣】健脾胃补中，治吐血，打损瘀血者熬焦酒服，能下恶血，又伤寒大毒嗽，于蔓青薤汁中煮一沸，顿服之良。 \n\n【宗奭】脾弱不思食人多用，能和胃气，亦用和药。  \n\n【禁忌】丹溪曰，饴属土，成于火，大发湿中之热，多食助脾风，能生胃火，此损齿之因，凡中满呕吐，酒病、牙疳，肾病及湿热证，不得轻投。  ","videoMemo":"","fangList":[],"bieMing":"饴糖"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '8、饴糖', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PWCSU7TwOMr', 4, '{"title":"第902001007条・第五章  增补神农本草经不足部分","description":"<p>7、紫苏  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001007,"note":"——本经无记载。  \n\n【产地】处处有之，为一年生之草本，叶之背面皆紫者佳，有香气。茎叶与子皆入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】紫苏为发表散寒解毒要药，功能降气化馾，发汗祛寒，主伤风寒热霍乱，肺气喘急，心腹胀满，安胎，妇人胎前宜之。 \n\n【别录】主下气，除寒热，其子尤良。 \n\n【孟铣】除寒热，治一切冷气。 \n\n【日华】补中益气，治心腹胀满，止霍乱转筋，开胃下食，止角气，通大小肠。 \n\n【苏颂】通心经，益脾胃。煮饮尤胜，与橘皮相宜。 \n\n【苏敬】下气消缓，虚者宜之，主安胎。 \n\n【用量】叶梗普通八分至二钱，苏子钱半至三钱。 \n\n【禁忌】凡阴虚因发寒热，或寒头痛者，宜敛宜补，不可用苏叶，火升作呕者亦忌，惟可用子，忌鲤鱼，同食发恶疮。 【容川】紫苏色红味辛香，能散血分肌肉中之寒，枝叶披离，故主散之性多，而主升之性少。苏子——主上气咳逆冷气，及腰脚中湿气，风结气，调中止霍乱，消五膈呕吐反胃，消痰止嗽，利大小便，治肺气喘急。   苏叶——主发散，盂铣曰苏子与苏叶同功，发散风气宜用叶，清利上下宜用子，近世多用以发散风寒，至化痰之力，则不如子也。主散气分之热，如喉为气之海。 苏梗——主顺气表散，汪昂曰，叶发汗散寒，梗顺气安胎，子开郁降气，消痰定喘。  ","videoMemo":"","fangList":[],"bieMing":"紫苏"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '7、紫苏', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9YPdY7pXVXm', 4, '{"title":"第902001006条・第五章  增补神农本草经不足部分","description":"<p>6、艾叶  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001006,"note":"——本经无记载。  \n\n【产地】生田野间，处处有之，陈久者良，有香味。 \n\n【性味】味苦，性征温，无毒。 \n\n【主治】艾叶为炙百病要药，并可作煎剂，主暖子宫，调经，止血，安胎。 \n\n【弘景】捣汁服止伤血，杀蚘虫。 \n\n【苏敬】主衄血下血脓血痢水，煮及丸散任用。 \n\n【甄权】止崩血肠痔，血搨金疮，止腹痛安胎，苦酒作煎治癣甚良，捣汁饮，冶心腹一切冷 气鬼气。 \n\n【大明】治带下，霍乱转筋，痢后寒热。 \n\n【好古】治带脉为病，腹胀满，腰溶溶如坐水中。 \n\n【容川】艾叶味苦而气温，其茸又能发火，是以能温肝补火，禀母木火之气，能入血室，女人经痛，乃凝血作痛，艾叶可去血室中之冷气也。补火之药是火能化水也，故能行血。 \n\n【用量】普通数分至钱半，炙用无定量。 \n\n【禁忌】妇女血热而月经超前者，宜慎用之。","videoMemo":"","fangList":[],"bieMing":"艾叶"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '6、艾叶', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cDT7bawaNcH', 4, '{"title":"第902001005条・第五章  增补神农本草经不足部分","description":"<p>5、赤小豆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001005,"note":"——本经无记载。  \n\n【产地】处处有之，以紧小者为良。  \n\n【性味】味辛（或作甘酸）性平，无毒。  \n\n【主治】赤小豆为行水散血，消肿解毒要药，主排痈肿脓血，水气肿账，治脚气，利小便，疗一切痈疽恶疮发背，内外可用。  \n\n【别录】疗寒热，热中消渴，止泄痢，利小便，下腹胀满，吐逆卒澼。  \n\n【甄权】治热毒，散恶血，除烦满，通气，健脾胃，令人美食，捣末同鸡子白涂一切热毒痈肿，煮汁洗小儿黄烂疮，不过三度。  \n\n【士良】缩气行风，坚筋骨，抽肌肉。  \n\n【孟铣】散气，去关节烦热，令人心孔开，暴痢后气满不能食者，煮食一顿即愈，和鲤鱼煮食，甚治脚气。  \n\n【日华】解小麦热毒，煮汁解酒毒，解衣粘缀。  \n\n【容川】赤小豆发芽，则能透达脓血。  \n\n【用量】普通钱半至三至四钱。  \n\n【禁忌】合鱼鲊食成消渴，作酱，同饭食成口疮，久服则降令太过，津血渗泄、令人肌瘦身重。  \n\n【容川】黏涩又味甘，能填补止泻利。  ","videoMemo":"","fangList":[],"bieMing":"赤小豆"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '5、赤小豆', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('plXQlwcSPJI', 4, '{"title":"第902001004条・第五章  增补神农本草经不足部分","description":"<p>4、蜘蛛  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001004,"note":"——本经无记载。  \n\n【产地】生原野，处处有之，种类甚多，取大腹深灰色，空中作圆网者，入药。  \n\n【性味】味缺，性微寒，有小毒。 \n\n【主治】蜘蛛主口瘑，瘰疬，结核，治蜈蚣蜂虿螫伤，宜外用，内服治干霍乱呕吐，脱肛，小儿大腹疳。  \n\n【别录】小儿大腹丁奚，三年不能行者。  \n\n【弘景】蜈蚣蜂虿螫人，取置咬处吸其毒。  \n\n【苏敬】主蛇毒，温疟，止呕逆霍乱。  \n\n【苏颂】取汁涂蛇伤，烧啖治小儿腹疳。  \n\n【日华】斑者治疟疾疔肿。  \n\n【用量】普通一至二钱。  \n\n【禁忌】有毒之物，可外用，少内服。凡使，去头足用，落在饮食中者不可食，畏蔓青雄黄，被蜘蛛咬中毒者，（一）用大篮汁一碗，入雄黄麝香少许，搽患处，仍服其汁。（二）用艾叶烧烟熏之。（三）羊乳灌之。（四）雄黄末敷之。  ","videoMemo":"","fangList":[],"bieMing":"蜘蛛"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '4、蜘蛛', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jNbTLyrZQsE', 4, '{"title":"第902001003条・第五章  增补神农本草经不足部分","description":"<p>3、红花  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001003,"note":" ——本经无记载。  \n\n【产地】产我国北地，今处处有之，园圃亦可栽植，为两年生之草本植物，花开色红，故名。\n\n【性味】味辛，性温，无毒。 \n\n【主治】红花为活血行瘀要药，主暴吐紫血，（紫则有瘀），产后血晕，痘疮血热有毒，（血行则毒解），治月经不调，腹中结块。  \n\n【开宝】主产后血运口噤，腹内恶血不尽，绞痛，胎死腹中，并酒煮服，亦主蛊毒。  \n\n【丹溪】多用破血，少用养血。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】忌沉香麝香，能使红花变色，可下死胎，孕妇忌用，过用红花，能使血行不止而毙。  \n\n【容川】色赤自入血分，味苦专能泄血，而花性专主轻扬，上行外走，故能泄肌肤脉络在外在上之血，有谚云：治风先治血，血行风自灭，血足则肝阳不动，而风自熄。观仲景之红蓝花酒，治风气百疾，则知治风先治血的道理。色红能生血，而味苦，又能泻血。  \n\n番红花——红花之产于新疆者，味甘性平无毒，主活血开郁，治心忧气闷，惊悸，伤寒发狂今多用为开胃行经之品。  \n\n藏红花——红花之产于西藏者，性味同红花，以入滚水内色如血，可冲四次不变色者为真，主活血通经治吐血（各种痞结冲汤服，忌食油荤盐），功用最良。 \n\n土红花——红花之产于福建者，根叶入药，味甘，性微寒，无毒，（或作有毒）治劳热瘴疟，骨节疼痛。  ","videoMemo":"","fangList":[],"bieMing":"红花"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '3、红花', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mDtcSKGP8dH', 4, '{"title":"第902001002条・第五章  增补神农本草经不足部分","description":"<p>2、诃黎勒（诃子）  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001002,"note":"\n【产地】产我国广东等地，其实六棱，又名诃黎勒。 \n\n【性味】味苦酸涩，性温，无毒。 \n\n【主治】诃子为涩肠治痢，保肺调气要药，主胸膈结气，心腹胀满，消痰，化食，通津，开胃，治心腹虚痛，肠风下血，崩带，胎漏，久痢，虚嗽。  \n\n 【唐本】主冷气。 \n\n【甄权】破胸膈结气，通利津液，止水道，黑髭发。  \n\n 【大明】消痰下气，化食开胃，除烦治水，调中止呕吐，霍乱心腹虚痛，奔豚肾气，肺气喘 息，五膈气，肠风泻血，崩中带下，怀孕漏胎，及动胎欲生，胀闷气喘，痢人肛门急痛，产妇阴痛，和蜡烧烟熏之及煎汤熏洗。 \n\n【萧柄】下宿物，止肠澼久泄赤白痢。 \n\n【苏敬】治痰嗽咽喉不利，合三数枚殊胜。 \n\n【丹溪】实大肠，敛肺降火。 \n\n【用量】普通一至二钱。 \n\n【禁忌】气虚宜缓缓少用，以此虽涩肠，而又泄气也，凡咳嗽痢疾初起者，均忌。  ","videoMemo":"","fangList":[],"bieMing":"诃黎勒"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2、诃黎勒（诃子）', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oua3U3Rr351', 4, '{"title":"第902001001条・第五章  增补神农本草经不足部分","description":"<p>1、青盐  ,戎盐</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902001001,"note":" ——即戎盐，补肾，泻血热。  \n\n【产地】产于我国内陆青海之盐。 \n\n【性味】甘咸而寒。入肾经。 \n\n【主治】助水脏，平血热，坚骨固齿，明目乌发。 \n\n【别录】治目痛赤涩，吐血溺血，齿舌出血。 \n\n【炮制】不假煎炼，方棱，明莹，色青者良， \n\n【用量】普通五分至一钱。 \n\n【禁忌】多食伤肺，走血，渗津，发渴。凡血病，哮喘，水肿，消渴人为大忌。  ","videoMemo":"","fangList":[],"bieMing":"青盐"}}', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '2025-01-17T09:24:22.000Z', '1、青盐 ,戎盐', '2025-01-17T09:24:22.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'sSWNdHHWzOX');
